R,C=19,29
ones={ (2,c) for c in [5,6,9,12,13,15,20,21,23]}
ones |= {(r,5) for r in [3,4,5,6,7,8,10,13,14,16]}
ones |= {(r,26) for r in [6,7,9,11,12,13,15,16]}
ones |= {(13,c) for c in [9,10,11,14,17,23]}
ones |= {(16,c) for c in [7,8,11,12,14,15,17,18,20,21,22]}
filled=set(ones)
for r in range(R):
 cs=sorted(c for rr,c in ones if rr==r)
 if len(cs)>1: filled.update((r,c) for c in range(cs[0],cs[-1]+1))
for c in range(C):
 rs=sorted(r for r,cc in ones if cc==c)
 if len(rs)>1: filled.update((r,c) for r in range(rs[0],rs[-1]+1))
grid=[[1 if (r,c) in ones else 2 if (r,c) in filled else 6 for c in range(C)] for r in range(R)]
print('\n'.join(map(str,grid)))

filled=set(ones)
for r in range(R):
 cs=sorted(c for rr,c in ones if rr==r)
 if len(cs)>=3: filled.update((r,c) for c in range(cs[0],cs[-1]+1))
for c in range(C):
 rs=sorted(r for r,cc in ones if cc==c)
 if len(rs)>=3: filled.update((r,c) for r in range(rs[0],rs[-1]+1))
grid2=[[1 if (r,c) in ones else 2 if (r,c) in filled else 6 for c in range(C)] for r in range(R)]
print('\n'.join(map(str,grid2)))

out=[[6 for c in range(C)] for r in range(R)]
for r,c in ones: out[r][c]=1
for c in range(5,27):
 for r in (2,16):
  if out[r][c]==6: out[r][c]=2
for r in range(2,17):
 for c in (5,26):
  if out[r][c]==6: out[r][c]=2
print('\n'.join(map(str,out)))
